export async function listModComments(modId: string, opts: { take?: number; cursor?: string } = {}): Promise<{ comments: ModComment[]; nextCursor: string | null }> {
  const take = opts.take ?? 10;
  const rows = await db.modRating.findMany({
    where: { gameModId: modId, comment: { not: null } },
    orderBy: { createdAt: "desc" },
    take: take + 1,
    ...(opts.cursor ? { cursor: { id: opts.cursor }, skip: 1 } : {}),
    include: { user: { select: { id: true, name: true } } },
  });
  const page = rows.slice(0, take);
  const nextCursor = rows.length > take ? page[page.length - 1]!.id : null;
  return {
    comments: page.map((r) => ({
      id: r.id,
      rating: r.rating,
      comment: r.comment!,
      createdAt: r.createdAt.toISOString(),
      userId: r.userId,
      userName: r.user.name,
    })),
    nextCursor,
  };
}

/** This viewer's own rating/comment on a mod, if they've left one — prefills the form as an edit rather than a fresh submit. */
export async function getMyModRating(modId: string, userId: string): Promise<{ rating: number; comment: string | null } | null> {
  const row = await db.modRating.findUnique({ where: { userId_gameModId: { userId, gameModId: modId } } });
  return row ? { rating: row.rating, comment: row.comment } : null;
}

/**
 * Real, case-insensitive search over name/category/description for one
 * family (or the whole catalog when family is omitted) — backs both the
 * marketing and portal search bars. Small catalogue, so a plain `findMany`
 * with `contains` is genuinely fine; no search index needed at this scale.
 */
export async function searchCatalogMods(query: string, family?: string): Promise<ModSummary[]> {
  const q = query.trim();
  if (!q) return listCatalogMods(family);
  const rows = await db.gameMod.findMany({
    where: {
      active: true,
      upstreamOk: true,
      ...(family ? { gameFamily: family } : {}),
      OR: [
        { name: { contains: q, mode: "insensitive" } },
        { category: { contains: q, mode: "insensitive" } },
        { description: { contains: q, mode: "insensitive" } },
      ],
    },
    orderBy: [{ featured: "desc" }, { downloads: "desc" }, { name: "asc" }],
  });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  return rows.map((r) => toSummary(r, aggs.get(r.id)));
}

export type RecommendedPlan = { planName: string; ramMB: number; priceCents: number } | null;

/**
 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
 * light-impact mods run on any active plan for the family; moderate needs at
 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
 * for the family that clears the bar, or null if none does (never guesses a
 * number that isn't a real, active, orderable plan).
 */
export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
  const pick = candidates[0];
  return pick ? { planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
}

