/**
 * Bulk-import the real Modrinth catalogue into `GameMod` — the "genuine
 * scale" pass NxLabs never had. Separate from `scripts/verify-gamemods.ts`,
 * which stays the per-mod re-verification/freshness-check tool for rows that
 * already exist (this script creates/updates rows in the first place; run
 * verify-gamemods.ts afterward on a schedule to keep them fresh and to
 * backfill fileBytes/impact/dependencyCount, which this script deliberately
 * does not touch — see "WHAT THIS DOES NOT FETCH" below).
 *
 * WHY THIS EXISTS. As of 2026-09-19 NxLabs has 119 real (of 124 seeded)
 * hand-picked mod rows across 5 families. Modrinth alone publishes ~158k real
 * projects. This script queries Modrinth's actual public search API, filters
 * to content that is genuinely installable on a DEDICATED SERVER (Nxeon's
 * product), and upserts real rows — every field traces to a live API
 * response, nothing here is fabricated.
 *
 * SOURCE: Modrinth REST API v2, https://docs.modrinth.com/api/ — a fully
 * public, documented, third-party-integration-friendly API (the same one
 * `scripts/verify-gamemods.ts` already calls; this script reuses its request
 * pattern: identifying User-Agent, optional API key header, real 429/5xx
 * backoff, no attempt to mirror/rehost files — only metadata + hotlinked CDN
 * images, files are fetched by the worker at install time, same as today).
 *
 * PROJECT TYPES COVERED: mod, plugin, resourcepack, shader, datapack,
 * modpack. Deliberately EXCLUDED: `minecraft_java_server` (Modrinth's own
 * dedicated server-jar listing product — not installable "content" the way
 * the six above are).
 *
 * SERVER-RELEVANCE FILTER: Modrinth's `environment` facet says whether a
 * project runs client, server, or both. We only import environments that are
 * meaningfully server-side: server_only, dedicated_server_only,
 * server_only_client_optional, client_and_server, client_or_server,
 * client_or_server_prefers_both. We exclude client_only / singleplayer_only
 * on purpose — Nxeon hosts dedicated servers, not client mods.
 *   ONE DELIBERATE EXCEPTION: for project_type "plugin" we ALSO accept
 *   environment "unknown". Reason (checked live against the real API, not
 *   guessed): "plugin" on Modrinth structurally means Bukkit/Spigot/
 *   Paper/Sponge/Velocity server software — there is no such thing as a
 *   client-only plugin — but a large fraction of real, popular, genuinely
 *   server-only plugins simply never got the environment field filled in by
 *   their author (verified live: project_type:plugin + our environment list
 *   + downloads>1000 = 141 hits; the SAME query without the environment
 *   filter = 3340 hits, and manually sampling the gap showed real, popular,
 *   unambiguously server-side plugins like Chunky and Simple Voice Chat
 *   tagged "unknown"/"client_or_server_prefers_both"). Excluding "unknown"
 *   for plugins specifically would throw away real, relevant, high-quality
 *   catalogue content over a data-entry gap, not a real client/server
 *   distinction. Every other project type keeps the strict list, because for
 *   mods/resourcepacks/shaders/modpacks "unknown" genuinely can mean
 *   client-only.
 *
 * QUALITY THRESHOLD (script constants below, override with --min-downloads /
 * --min-follows): downloads > 1000 OR follows > 50. Implemented as two
 * disjoint search passes (Modrinth facets AND within a query; there is no
 * single-query OR across two different numeric fields) — pass 1 sorts by
 * downloads and takes everything over the download floor, pass 2 sorts by
 * follows and takes everything over the follow floor that pass 1 didn't
 * already take (`downloads<=floor`), so nothing is double-counted across
 * passes (cross-project-type duplicates from Modrinth's own
 * `all_project_types` overlap are still possible and handled by the
 * `seenProjectIds` set + the `@@unique([gameFamily, slug])` upsert either
 * way).
 *
 * WHAT THIS DOES NOT FETCH (by design, to keep this a fast, few-thousand-
 * request bulk pass rather than a many-hour one): fileBytes,
 * dependencyCount, impact/impactNote. Those need a per-project `/version`
 * call each and are exactly what `verify-gamemods.ts` already does well —
 * re-run it with `--source=modrinth` after this script to backfill them, at
 * whatever pace is comfortable, on however many thousand rows this leaves it.
 *
 * EFFICIENCY: uses Modrinth's *bulk* endpoints so a page of 100 search hits
 * costs 3 requests total, not ~300: one `/v2/search` call, one
 * `/v2/projects?ids=[...]` call for the full record (clean `loaders` array
 * separate from tags, real `license` object, full `gallery` with
 * featured/ordering metadata, `server_side`), and one `/v2/users?ids=[...]`
 * call for real author avatars (search hits already carry `author`/
 * `author_id` directly — no team-lookup round trip needed the way a
 * single-project verify does).
 *
 * RATE LIMIT: 300 req/min per Modrinth, same with or without the API key (the
 * key just avoids being rejected as an unidentified client — real
 * contact-bearing User-Agent sent regardless). This script paces itself under
 * that (see RATE_LIMIT_PER_MIN) and retries 429s honoring `Retry-After`.
 *
 * IDEMPOTENT: every write is `db.gameMod.upsert` on the real
 * `@@unique([gameFamily, slug])` constraint — re-running updates the same
 * rows, never duplicates.
 *
 * SAFETY: this is a bulk-WRITE script against a real database, so it goes
 * through the same NXEON_DB_TARGET confirmation every other writing script in
 * this repo uses (scripts/db-target-guard.ts) and defaults to a dry run.
 *
 *   Dry run (no writes), one type, tiny slice — the sane way to first try this:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-modrinth-catalog.ts \
 *       --project-types=mod --max-pages=1
 *
 *   Real write, one type, tiny slice:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-modrinth-catalog.ts \
 *       --project-types=mod --max-pages=1 --apply
 *
 *   Full real run (all 6 types, default thresholds):
 *     NXEON_DB_TARGET=nxeon npx tsx scripts/import-modrinth-catalog.ts --apply
 */

import { assertDbTarget } from "./db-target-guard";
assertDbTarget("import-modrinth-catalog.ts");

import { db } from "../lib/db";

const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
const MODRINTH_KEY = process.env.MODRINTH_API_KEY ?? "";
const API = "https://api.modrinth.com/v2";

// ── Tunable script constants (all overridable via CLI flags, see parseArgs) ──
const DEFAULT_MIN_DOWNLOADS = 1000;
const DEFAULT_MIN_FOLLOWS = 50;
const DEFAULT_RATE_LIMIT_PER_MIN = 280; // stay under Modrinth's real 300/min
const PAGE_SIZE = 100; // Modrinth's real server-side cap on `limit`
const GALLERY_CAP = 8; // matches verify-gamemods.ts's convention

const ALL_PROJECT_TYPES = ["mod", "plugin", "resourcepack", "shader", "datapack", "modpack"] as const;
type ProjectType = (typeof ALL_PROJECT_TYPES)[number];

const CATEGORY_LABEL: Record<ProjectType, string> = {
  mod: "Mods",
  plugin: "Plugins",
  resourcepack: "Resource Packs",
  shader: "Shaders",
  datapack: "Datapacks",
  modpack: "Modpacks",
};

/** Real, server-relevant Modrinth `environment` values (see file header). */
const SERVER_ENVIRONMENTS = [
  "server_only",
  "dedicated_server_only",
  "server_only_client_optional",
  "client_and_server",
  "client_or_server",
  "client_or_server_prefers_both",
];

function environmentsFor(pt: ProjectType): string[] {
  // See file header: plugins are structurally server-only software even when
  // the author never filled in the environment field.
  return pt === "plugin" ? [...SERVER_ENVIRONMENTS, "unknown"] : SERVER_ENVIRONMENTS;
}

// ── CLI args ──────────────────────────────────────────────────────────────
function parseArgs(argv: string[]) {
  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
  const projectTypesArg = get("project-types");
  const projectTypes = (projectTypesArg ? projectTypesArg.split(",") : [...ALL_PROJECT_TYPES]).filter(
    (t): t is ProjectType => (ALL_PROJECT_TYPES as readonly string[]).includes(t)
  );
  return {
    apply: argv.includes("--apply"),
    minDownloads: Number(get("min-downloads") ?? DEFAULT_MIN_DOWNLOADS),
    minFollows: Number(get("min-follows") ?? DEFAULT_MIN_FOLLOWS),
    ratePerMin: Number(get("rate-per-min") ?? DEFAULT_RATE_LIMIT_PER_MIN),
    // Cap pages PER (project type × pass) — for smoke-testing a slice, not a real-run knob.
    maxPages: get("max-pages") ? Number(get("max-pages")) : undefined,
    projectTypes: projectTypes.length ? projectTypes : [...ALL_PROJECT_TYPES],
  };
}

// ── Rate-limited, retrying fetch ─────────────────────────────────────────
class RateLimiter {
  private minIntervalMs: number;
  private last = 0;
  constructor(perMin: number) {
    this.minIntervalMs = 60_000 / perMin;
  }
  async wait() {
    const now = Date.now();
    const elapsed = now - this.last;
    if (elapsed < this.minIntervalMs) {
      await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
    }
    this.last = Date.now();
  }
}

async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
  await limiter.wait();
  const headers: Record<string, string> = { "User-Agent": UA };
  if (MODRINTH_KEY) headers.Authorization = MODRINTH_KEY;
  const res = await fetch(url, { headers });
  if (res.status === 429 && attempt <= 6) {
    const retryAfterHeader = res.headers.get("retry-after");
    const retryAfterMs = retryAfterHeader ? Number(retryAfterHeader) * 1000 : 0;
    const backoffMs = Math.max(retryAfterMs, 1000 * 2 ** attempt);
    console.warn(`  [rate-limit] 429 on ${url} — backing off ${Math.round(backoffMs / 1000)}s (attempt ${attempt})`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return apiFetch(limiter, url, attempt + 1);
  }
  if (res.status >= 500 && attempt <= 4) {
    const backoffMs = 1000 * 2 ** attempt;
    console.warn(`  [server-error] ${res.status} on ${url} — retrying in ${Math.round(backoffMs / 1000)}s`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return apiFetch(limiter, url, attempt + 1);
  }
  return res;
}

// ── Modrinth types (only the fields we read) ─────────────────────────────
type SearchHit = {
  project_id: string;
  project_type: string;
  slug: string;
  author: string | null;
  author_id: string | null;
  title: string;
  description: string;
  downloads: number;
  follows: number;
  icon_url: string | null;
};
type SearchResponse = { hits: SearchHit[]; total_hits: number };

type FullProject = {
  id: string;
  slug: string;
  license?: { id?: string | null; name?: string | null } | null;
  game_versions?: string[];
  loaders?: string[];
  server_side?: string;
  downloads?: number;
  followers?: number;
  icon_url?: string | null;
  gallery?: Array<{ url: string; featured?: boolean; ordering?: number }>;
};

type UserRecord = { id: string; username: string; avatar_url?: string | null };

function facetQuery(pt: ProjectType, envs: string[], extra: string[], limit: number, offset: number, sortIndex: string): string {
  const facets = [[`project_type:${pt}`], envs.map((e) => `environment:${e}`), ...extra.map((e) => [e])];
  const encoded = encodeURIComponent(JSON.stringify(facets));
  return `${API}/search?facets=${encoded}&limit=${limit}&offset=${offset}&index=${sortIndex}`;
}

/** Real gallery URLs, featured-first then by real `ordering`, capped — matches verify-gamemods.ts. */
function galleryUrlsFrom(gallery: FullProject["gallery"]): string[] {
  return (gallery ?? [])
    .slice()
    .sort((a, b) => Number(b.featured) - Number(a.featured) || (a.ordering ?? 0) - (b.ordering ?? 0))
    .slice(0, GALLERY_CAP)
    .map((g) => g.url);
}

type Counters = { searched: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
function emptyCounters(): Counters {
  return { searched: 0, upserted: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
}

async function importPass(opts: {
  pt: ProjectType;
  facetsExtra: string[];
  sortIndex: string;
  limiter: RateLimiter;
  apply: boolean;
  maxPages?: number;
  seenProjectIds: Set<string>;
  counters: Counters;
}) {
  const { pt, facetsExtra, sortIndex, limiter, apply, maxPages, seenProjectIds, counters } = opts;
  const envs = environmentsFor(pt);
  let offset = 0;
  let page = 0;
  // First call establishes total_hits; loop until we've paged through it (or hit --max-pages).
  for (;;) {
    if (maxPages !== undefined && page >= maxPages) break;
    const url = facetQuery(pt, envs, facetsExtra, PAGE_SIZE, offset, sortIndex);
    const res = await apiFetch(limiter, url);
    if (!res.ok) {
      console.error(`  [search] ${pt} offset=${offset} → HTTP ${res.status}, stopping this pass early`);
      break;
    }
    const body = (await res.json()) as SearchResponse;
    page++;
    counters.searched += body.hits.length;
    if (body.hits.length === 0) break;

    const fresh = body.hits.filter((h) => !seenProjectIds.has(h.project_id));
    for (const h of fresh) seenProjectIds.add(h.project_id);

    if (fresh.length > 0) {
      // Bulk-fetch full project records (loaders/license/gallery/server_side) —
      // one request for up to 100 mods, per the file header's efficiency note.
      const idsParam = encodeURIComponent(JSON.stringify(fresh.map((h) => h.project_id)));
      const projRes = await apiFetch(limiter, `${API}/projects?ids=${idsParam}`);
      const fullProjects: FullProject[] = projRes.ok ? await projRes.json() : [];
      const fullById = new Map(fullProjects.map((p) => [p.id, p]));

      // Bulk-fetch real author avatars for every unique author_id on this page.
      const authorIds = [...new Set(fresh.map((h) => h.author_id).filter((x): x is string => !!x))];
      let userById = new Map<string, UserRecord>();
      if (authorIds.length > 0) {
        const uidsParam = encodeURIComponent(JSON.stringify(authorIds));
        const usersRes = await apiFetch(limiter, `${API}/users?ids=${uidsParam}`);
        if (usersRes.ok) {
          const users: UserRecord[] = await usersRes.json();
          userById = new Map(users.map((u) => [u.id, u]));
        }
      }

      // DB writes are local Postgres — safe to run a small batch concurrently
      // (the API calls above stay strictly sequential/rate-limited; this isn't).
      const CONCURRENCY = 8;
      for (let i = 0; i < fresh.length; i += CONCURRENCY) {
        const slice = fresh.slice(i, i + CONCURRENCY);
        await Promise.all(
          slice.map(async (hit) => {
            if (!hit.slug) {
              counters.skipped++;
              return;
            }
            const full = fullById.get(hit.project_id);
            const author = hit.author_id ? userById.get(hit.author_id) : undefined;
            const data = {
              name: hit.title,
              category: CATEGORY_LABEL[pt],
              description: hit.description || null,
              iconUrl: full?.icon_url ?? hit.icon_url ?? null,
              url: `https://modrinth.com/${pt}/${hit.slug}`,
              downloads: full?.downloads ?? hit.downloads ?? null,
              license: full?.license?.id || full?.license?.name || null,
              gameVersions: full?.game_versions ?? [],
              loaders: full?.loaders ?? [],
              serverSide: full?.server_side ?? null,
              galleryUrls: galleryUrlsFrom(full?.gallery),
              authorName: hit.author ?? null,
              authorAvatarUrl: author?.avatar_url ?? null,
              source: "modrinth",
              sourceId: hit.slug,
              active: true,
              verifiedAt: new Date(),
              upstreamOk: true,
              upstreamNote: null,
            };
            if (!apply) {
              counters.upserted++;
              return;
            }
            try {
              const existing = await db.gameMod.findUnique({
                where: { gameFamily_slug: { gameFamily: "minecraft", slug: hit.slug } },
                select: { id: true },
              });
              await db.gameMod.upsert({
                where: { gameFamily_slug: { gameFamily: "minecraft", slug: hit.slug } },
                update: data,
                create: { gameFamily: "minecraft", slug: hit.slug, ...data },
              });
              counters.upserted++;
              if (existing) counters.updated++;
              else counters.created++;
            } catch (e) {
              counters.failed++;
              const msg = e instanceof Error ? e.message : String(e);
              console.error(`  [db] failed to upsert ${pt}/${hit.slug}: ${msg}`);
            }
          })
        );
      }
    }

    console.log(
      `  [${pt}/${sortIndex}] page=${page} offset=${offset} hits=${body.hits.length} fresh=${fresh.length} total_hits=${body.total_hits} ` +
        `(running: searched=${counters.searched} upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} skipped=${counters.skipped} failed=${counters.failed})`
    );

    offset += PAGE_SIZE;
    if (offset >= body.total_hits) break;
  }
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  console.log(
    `[import-modrinth-catalog] ${args.apply ? "APPLY (writing)" : "DRY RUN (no writes)"} — ` +
      `project types: ${args.projectTypes.join(", ")}; threshold: downloads>${args.minDownloads} OR follows>${args.minFollows}; ` +
      `rate: ${args.ratePerMin}/min${args.maxPages ? `; max-pages=${args.maxPages} (smoke test)` : ""}`
  );

  const limiter = new RateLimiter(args.ratePerMin);
  const seenProjectIds = new Set<string>();
  const totals = emptyCounters();
  const perType: Record<string, Counters> = {};

  for (const pt of args.projectTypes) {
    const counters = emptyCounters();
    perType[pt] = counters;
    console.log(`\n=== ${pt} ===`);

    // Pass 1: downloads > floor, sorted by downloads (highest quality first).
    await importPass({
      pt,
      facetsExtra: [`downloads>${args.minDownloads}`],
      sortIndex: "downloads",
      limiter,
      apply: args.apply,
      maxPages: args.maxPages,
      seenProjectIds,
      counters,
    });

    // Pass 2: follows > floor AND downloads <= floor (disjoint from pass 1),
    // sorted by follows — catches real, followed-but-newer projects pass 1 missed.
    await importPass({
      pt,
      facetsExtra: [`follows>${args.minFollows}`, `downloads<=${args.minDownloads}`],
      sortIndex: "follows",
      limiter,
      apply: args.apply,
      maxPages: args.maxPages,
      seenProjectIds,
      counters,
    });

    for (const k of Object.keys(totals) as (keyof Counters)[]) totals[k] += counters[k];
    console.log(
      `--- ${pt} done: searched=${counters.searched} upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} skipped=${counters.skipped} failed=${counters.failed} ---`
    );
  }

  console.log(`\n============================================================`);
  console.log(`FINAL SUMMARY (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
  for (const pt of args.projectTypes) {
    const c = perType[pt]!;
    console.log(
      `  ${pt.padEnd(13)} searched=${c.searched.toString().padStart(6)} upserted=${c.upserted.toString().padStart(6)} created=${c.created.toString().padStart(6)} updated=${c.updated.toString().padStart(6)} skipped=${c.skipped} failed=${c.failed}`
    );
  }
  console.log(`  ${"TOTAL".padEnd(13)} searched=${totals.searched.toString().padStart(6)} upserted=${totals.upserted.toString().padStart(6)} created=${totals.created.toString().padStart(6)} updated=${totals.updated.toString().padStart(6)} skipped=${totals.skipped} failed=${totals.failed}`);
  console.log(`  unique projects seen across all passes: ${seenProjectIds.size}`);
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

